// Cracked glass — animated Voronoi cells with dark borders
uniform float uScale;   // @param 6.0 1.0 20.0
uniform float uBorder;  // @param 0.04 0.0 0.25
uniform float uSpeed;   // @param 0.4 0.0 3.0
uniform vec3  uTint;    // @param #8FC8E8
uniform vec3  uEdge;    // @param #050608

vec2 hash2(vec2 p) {
  p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
  return fract(sin(p) * 43758.5453);
}

vec2 cellPoint(vec2 c, float t) {
  vec2 h = hash2(c);
  return 0.5 + 0.4 * sin(t + 6.2831 * h);
}

// Returns distance to nearest cell border; outputs cell id and vector to seed.
float voronoi(vec2 x, float t, out vec2 id, out vec2 toSeed) {
  vec2 n = floor(x);
  vec2 f = fract(x);
  vec2 mg = vec2(0.0);
  vec2 mr = vec2(0.0);
  float md = 8.0;
  for (int j = -1; j <= 1; j++) {
    for (int i = -1; i <= 1; i++) {
      vec2 g = vec2(float(i), float(j));
      vec2 r = g + cellPoint(n + g, t) - f;
      float d = dot(r, r);
      if (d < md) { md = d; mr = r; mg = g; }
    }
  }
  md = 8.0;
  for (int j = -2; j <= 2; j++) {
    for (int i = -2; i <= 2; i++) {
      vec2 g = mg + vec2(float(i), float(j));
      vec2 r = g + cellPoint(n + g, t) - f;
      vec2 dr = r - mr;
      if (dot(dr, dr) > 1e-5) {
        md = min(md, dot(0.5 * (mr + r), normalize(dr)));
      }
    }
  }
  id = n + mg;
  toSeed = mr;
  return md;
}

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  float t = iTime * uSpeed;

  vec2 id, toSeed;
  float d = voronoi(p * uScale, t, id, toSeed);

  // Per-cell glass shard color with faceted lighting
  vec2 h = hash2(id);
  vec3 col = uTint * (0.45 + 0.55 * h.x);
  vec2 dir = normalize(toSeed + 1e-4);
  float facet = dot(dir, normalize(vec2(0.6 + 0.4 * h.y, 0.8)));
  col *= 0.75 + 0.35 * facet;
  col += 0.08 * fbm(p * uScale * 1.5 + id);

  // Bright rim just inside each crack
  float aa = max(fwidth(d), 1e-4);
  float rim = 1.0 - smoothstep(uBorder, uBorder + 0.08, d);
  col += rim * 0.35 * (0.5 + 0.5 * h.y);

  // Dark crack border
  float edge = 1.0 - smoothstep(uBorder - aa, uBorder + aa, d);
  col = mix(col, uEdge, edge);

  float vig = 1.0 - 0.5 * dot(p, p);
  fragColor = vec4(col * vig, 1.0);
}
